class Manager {
    private String name;
    private List<Object> reports = new ArrayList<>();

    public Manager(String name) { this.name = name; }

    public void add(Object item) { reports.add(item); }

    public int getSalary() {
        int total = 0;
        for (Object item : reports) {
            if (item instanceof Employee) {
                total += ((Employee) item).getSalary();
            } else if (item instanceof Manager) {
                total += ((Manager) item).getSalary();
            }
        }
        return total;
    }

    public void printStructure(String indent) {
        System.out.println(indent + name + " [Manager]");
        for (Object item : reports) {
            if (item instanceof Employee) {
                ((Employee) item).printStructure(indent + "  ");
            } else if (item instanceof Manager) {
                ((Manager) item).printStructure(indent + "  ");
            }
        }
    }

    public void remove() {
        for (Object item : reports) {
            if (item instanceof Employee) {
                ((Employee) item).remove();
            } else if (item instanceof Manager) {
                ((Manager) item).remove();
            }
        }
        System.out.println("Removing manager: " + name);
    }
}

