#include <bits/stdc++.h>
using namespace std;

class Base {
public:
    virtual ~Base() = default;
};

class Employee : public Base {
    string name;
    int salary;
public:
    Employee(string name, int salary) : name(name), salary(salary) {}
    int getSalary() { return salary; }
    void printStructure(string indent) { cout << indent << name << endl; }
    void remove() { cout << "Removing employee: " << name << endl; }
};

class Manager : public Base {
    string name;
    vector<Base*> reports;
public:
    Manager(string name) : name(name) {}
    void add(Base* item) { reports.push_back(item); }

    int getSalary() {
        int total = 0;
        for (auto item : reports) {
            if (auto e = dynamic_cast<Employee*>(item)) total += e->getSalary();
            else if (auto m = dynamic_cast<Manager*>(item)) total += m->getSalary();
        }
        return total;
    }

    void printStructure(string indent) {
        cout << indent << name << " [Manager]" << endl;
        for (auto item : reports) {
            if (auto e = dynamic_cast<Employee*>(item)) e->printStructure(indent + "  ");
            else if (auto m = dynamic_cast<Manager*>(item)) m->printStructure(indent + "  ");
        }
    }

    void remove() {
        for (auto item : reports) {
            if (auto e = dynamic_cast<Employee*>(item)) e->remove();
            else if (auto m = dynamic_cast<Manager*>(item)) m->remove();
        }
        cout << "Removing manager: " << name << endl;
    }
};

int main() {
    Employee dev1("Developer 1", 80000);
    Employee dev2("Developer 2", 75000);

    Manager engManager("Engineering Manager");
    engManager.add(&dev1);
    engManager.add(&dev2);

    cout << "Total salary: " << engManager.getSalary() << endl;
    engManager.printStructure("");
