class OrgMember(ABC):
    @abstractmethod
    def get_salary(self):
        pass

    @abstractmethod
    def print_structure(self, indent):
        pass

    @abstractmethod
    def remove(self):
        pass


class Employee(OrgMember):
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def get_salary(self):
        return self.salary

    def print_structure(self, indent):
        print(f"{indent}- {self.name} (${self.salary})")

    def remove(self):
        print(f"Removing employee: {self.name}")


class Manager(OrgMember):
    def __init__(self, name):
        self.name = name
        self.reports = []

    def add_member(self, member):
        self.reports.append(member)

    def remove_member(self, member):
        self.reports.remove(member)

    def get_salary(self):
        total = 0
        for member in self.reports:
            total += member.get_salary()
        return total

    def print_structure(self, indent):
        print(f"{indent}+ {self.name} [Manager]")
        for member in self.reports:
            member.print_structure(indent + "  ")

    def remove(self):
        for member in self.reports:
            member.remove()
        print(f"Removing manager: {self.name}")


if __name__ == "__main__":
    employee = Employee("Developer 1", 80000)
    manager = Manager("Engineering Manager")
