    void remove();
}

class Employee implements OrgMember {
    private final String name;
    private final int salary;

    public Employee(String name, int salary) {
        this.name = name;
        this.salary = salary;
    }

    @Override
    public int getSalary() {
        return salary;
    }

    @Override
    public void printStructure(String indent) {
        System.out.println(indent + "- " + name + " ($" + salary + ")");
    }

    @Override
    public void remove() {
        System.out.println("Removing employee: " + name);
    }
}

class Manager implements OrgMember {
    private final String name;
    private final List<OrgMember> reports = new ArrayList<>();

    public Manager(String name) {
        this.name = name;
    }

    public void addMember(OrgMember member) {
        reports.add(member);
    }

    public void removeMember(OrgMember member) {
        reports.remove(member);
    }

    @Override
    public int getSalary() {
        int total = 0;
        for (OrgMember member : reports) {
            total += member.getSalary();
        }
        return total;
    }

    @Override
    public void printStructure(String indent) {
        System.out.println(indent + "+ " + name + " [Manager]");
        for (OrgMember member : reports) {
            member.printStructure(indent + "  ");
        }
    }

    @Override
    public void remove() {
        for (OrgMember member : reports) {
            member.remove();
        }
        System.out.println("Removing manager: " + name);
    }
}

public class Main {
    public static void main(String[] args) {
        OrgMember employee = new Employee("Developer 1", 80000);
        Manager managerObj = new Manager("Engineering Manager");
        managerObj.addMember(employee);
        OrgMember manager = managerObj;

        List<OrgMember> team = List.of(employee, manager);
        for (OrgMember member : team) {
            member.remove();
        }
    }
}

