#include <bits/stdc++.h>
using namespace std;

class OrgMember {
public:
    virtual int getSalary() = 0;
    virtual void printStructure(const string& indent) = 0;
    virtual void remove() = 0;
    virtual ~OrgMember() = default;
};

class Employee : public OrgMember {
    string name;
    int salary;
public:
    Employee(string name, int salary) : name(name), salary(salary) {}

    int getSalary() override { return salary; }

    void printStructure(const string& indent) override {
        cout << indent << "- " << name << " ($" << salary << ")" << endl;
    }

    void remove() override {
        cout << "Removing employee: " << name << endl;
    }
};

class Manager : public OrgMember {
    string name;
    vector<OrgMember*> reports;
public:
    Manager(string name) : name(name) {}

    void addMember(OrgMember* member) { reports.push_back(member); }
    void removeMember(OrgMember* member) {
        reports.erase(std::remove(reports.begin(), reports.end(), member), reports.end());
    }

    int getSalary() override {
        int total = 0;
        for (auto member : reports) total += member->getSalary();
        return total;
    }

    void printStructure(const string& indent) override {
        cout << indent << "+ " << name << " [Manager]" << endl;
        for (auto member : reports) member->printStructure(indent + "  ");
    }

    void remove() override {
        for (auto member : reports) member->remove();
        cout << "Removing manager: " << name << endl;
    }
};

int main() {
    Employee employee("Developer 1", 80000);
    Manager manager("Engineering Manager");
    manager.addMember(&employee);

    vector<OrgMember*> team = { &employee, &manager };
    for (auto member : team) {
        member->remove();
    }
    return 0;
}

