class UniversityComponent {
public:
    virtual int getBudget() = 0;
    virtual int getHeadcount() = 0;
    virtual void printHierarchy(const string& indent) = 0;
    virtual ~UniversityComponent() = default;
};

class Professor : public UniversityComponent {
    string name;
    string role;
    int budget;
public:
    Professor(string name, string role, int budget) : name(name), role(role), budget(budget) {}

    int getBudget() override { return budget; }
    int getHeadcount() override { return 1; }

    void printHierarchy(const string& indent) override {
        cout << indent << "- " << name << " (" << role << ", $" << budget << ")" << endl;
    }
};

class Department : public UniversityComponent {
    string name;
    string role;
    int budget;
    vector<UniversityComponent*> members;
public:
    Department(string name, string role, int budget) : name(name), role(role), budget(budget) {}

    void addMember(UniversityComponent* member) { members.push_back(member); }
    void removeMember(UniversityComponent* member) {
        members.erase(std::remove(members.begin(), members.end(), member), members.end());
    }

    int getBudget() override {
        int total = budget;
        for (auto member : members) total += member->getBudget();
        return total;
    }

    int getHeadcount() override {
        int count = 1;
        for (auto member : members) count += member->getHeadcount();
        return count;
    }

    void printHierarchy(const string& indent) override {
        cout << indent << "+ " << name << " (" << role << ", $" << budget << ")" << endl;
        for (auto member : members) member->printHierarchy(indent + "  ");
    }
};

